<?php
declare(strict_types=1);
require __DIR__ . '/platform-admin/src/public-bootstrap.php';
$slug = strtolower(trim((string)($_GET['slug'] ?? '')));
if (!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/', $slug)) { http_response_code(404); exit('Product not found.'); }
$stmt=public_db()->prepare("SELECT id,slug,name,summary,tagline,description,features,benefits,target_audience,youtube_url,hero_image_url,meta_title,meta_description FROM platform_products WHERE slug=? AND status='published' LIMIT 1");
$stmt->bind_param('s',$slug); $stmt->execute();
$product=$stmt->get_result()->fetch_assoc();
if (!$product) { http_response_code(404); exit('Product not found.'); }
function product_lines($value): array { return array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',(string)$value)),function($v){return $v!=='';})); }
function youtube_embed_id($url): string {
    $host=strtolower((string)parse_url($url,PHP_URL_HOST)); $path=(string)parse_url($url,PHP_URL_PATH); $id='';
    if ($host==='youtu.be') $id=trim($path,'/');
    elseif (in_array($host,['youtube.com','www.youtube.com','m.youtube.com'],true)) {
        if (strpos($path,'/embed/')===0) $id=substr($path,7);
        elseif (strpos($path,'/shorts/')===0) $id=substr($path,8);
        else parse_str((string)parse_url($url,PHP_URL_QUERY),$q); if (isset($q['v'])) $id=(string)$q['v'];
    }
    return preg_match('/^[A-Za-z0-9_-]{11}$/',$id)?$id:'';
}
$videoId=$product['youtube_url']?youtube_embed_id($product['youtube_url']):'';
$title=$product['meta_title'] ?: $product['name'].' | SmarterNow Data Venture';
$description=$product['meta_description'] ?: $product['summary'];
$features=product_lines($product['features']); $benefits=product_lines($product['benefits']);
